#include <iostream>

// Compile-time Factorial via Class Template Recursion
template <unsigned N>
struct Factorial {
    static constexpr unsigned value = N * Factorial<N - 1>::value;
};

// Base case specialization
template <>
struct Factorial<0> {
    static constexpr unsigned value = 1;
};

int main() {
    std::cout << Factorial<5>::value; // Evaluated at compile time (120)
}

template <int N>
struct Square {
    static constexpr int ___ = N * N;
};

template <typename T>
struct Identity {
    using ___ = T;
};

template <unsigned N>
struct Fibonacci {
    static constexpr unsigned value = Fibonacci<N-1>::value + Fibonacci<N-2>::value;
};

template <>
struct Fibonacci<1> {
    static constexpr unsigned value = ___
};
